With the same conditions as \Cref{le_sizes_of_RandW}, the suboptimality for Off-C$^2$LUB satisfies:
\begin{align}\label{align_in_th2}
\textnormal{SubOpt}(u_{\textnormal{test}},\textnormal{Off-C}^2\textnormal{LUB},\mathcal{A}_{\textnormal{test}})\leq \tilde O\left( \sqrt{\frac{d}{\tilde \lambda_aN_{\mathcal{V}_{\hat\gamma}(u_{\textnormal{test}})}}} + \frac{\eta_{\mathcal{W}_{\hat\gamma}(u_{\textnormal{test}})}\hat\gamma}{\tilde \lambda_a} \right),
\end{align}
with probability at least $1-2\delta$

Then, with probability at least $1-2\delta$, the suboptimality of Off-C$^2$LUB satisfies
\begin{align}
\textnormal{SubOpt}(u_{\textnormal{test}}, \textnormal{Off-C}^2\textnormal{LUB}, \mathcal{A}_{\textnormal{test}})
\leq \tilde O \left( 
\sqrt{\frac{d}{\tilde \lambda_a N_{\tilde{\mathcal R}_{\hat\gamma}(u_{\text{test}})}}}
+ \frac{\eta_{\tilde{\mathcal{W}}_{\hat\gamma}(u_{\text{test}})} \hat\gamma}{\tilde \lambda_a} 
\right).
\end{align}
